{"summary": "Create IPython atheris-based fuzz driver fuzz.py", "command": "create", "path": "/app/ipython/fuzz.py", "file_text": "#!/usr/bin/env python3
import sys

import atheris

with atheris.instrument_imports():
    from IPython.core.inputtransformer2 import TransformerManager

try:
    from tokenize import TokenError
except Exception:  # pragma: no cover
    TokenError = Exception

_TM = TransformerManager()


@atheris.instrument_func
def TestOneInput(data: bytes) -> None:
    data = data[:20000]
    s = data.decode("utf-8", errors="ignore")
    if not s:
        return

    try:
        _TM.transform_cell(s)
    except (SyntaxError, IndentationError, TokenError, ValueError):
        # Expected for malformed python/IPython inputs.
        return


def main() -> None:
    atheris.Setup(sys.argv, TestOneInput)
    atheris.Fuzz()


if __name__ == "__main__":
    main()
", "security_risk": "LOW"}

{"summary": "Create ujson atheris-based fuzz driver fuzz.py", "command": "create", "path": "/app/ujson/fuzz.py", "file_text": "#!/usr/bin/env python3
import sys

import atheris

with atheris.instrument_imports():
    import ujson


@atheris.instrument_func
def TestOneInput(data: bytes) -> None:
    # Bound input size; JSON parsers can be quadratic on some patterns.
    data = data[:20000]

    try:
        # Exercise both bytes and str entry paths.
        if data and data[0] % 2 == 0:
            ujson.loads(data)
        else:
            s = data.decode("utf-8", errors="ignore")
            ujson.loads(s)
    except (ValueError, OverflowError):
        return


def main() -> None:
    atheris.Setup(sys.argv, TestOneInput)
    atheris.Fuzz()


if __name__ == "__main__":
    main()
", "security_risk": "LOW"}

{"summary": "Create per-library .venv environments and install deps plus atheris", "command": "for lib in arrow black ipython minisgl ujson; do
  echo "\n========================";
  echo "Setting up venv for $lib";
  cd /app/$lib || exit 1;
  if [ ! -d .venv ]; then
    uv venv >/dev/null;
  fi;
  if [ "$lib" = "minisgl" ]; then
    # Avoid pulling extremely heavy ML dependencies; we only fuzz env parsing.
    uv pip install -e . --no-deps;
  else
    uv pip install -e .;
  fi;
  uv pip install atheris;
  mkdir -p corpus;
done", "timeout": 1200, "security_risk": "MEDIUM"}

{"summary": "Run each fuzz.py for 10 seconds and save output logs", "command": "for lib in arrow black ipython minisgl ujson; do
  echo "\n=== Running fuzzer for $lib ===";
  cd /app/$lib || exit 1;
  /app/$lib/.venv/bin/python fuzz.py -max_total_time=10 corpus > fuzz.log 2>&1 || true;
  echo "  wrote $(wc -c < fuzz.log) bytes to fuzz.log";
done", "timeout": 180, "security_risk": "MEDIUM"}

